"""Publish explicit coverage, failures and unknowns; source rows are not physical buildings."""
import json,csv,shutil
from pathlib import Path
from nyc.download import ROOT,atomic_json,now,sha

def read(path):return json.loads((ROOT/path).read_text())
city=read('reports/city-quality.json');dims={r['borough']:r for r in read('reports/city-dimensions.json')['boroughs']};inventory=read('reports/source-city-inventory.json')
rows=[]
for r in city['boroughs']:
 d=dims[r['borough']];rows.append({**r,**{k:v for k,v in d.items()if k not in ['borough','raw_records']},'nonplaceholder_source_records':r['raw_records']-d['placeholders'],'unknown_height_records':r['raw_records']-r['valid_source_height_records']})
raw_total=sum(r['raw_records']for r in rows)
if raw_total!=inventory['counts']['all']or raw_total!=city['rows']:raise ValueError('city inventory/capture/normalization count mismatch')
pilots=[read(f'data/processed/{n}/quality.json')for n in ['lower-manhattan','midtown','brooklyn-dumbo','queens-lic','bronx-mott-haven','staten-st-george']]
report={'schema_version':1,'generated_at':now(),'scope':'2026-10-27-city capture; boroughs partitioned by source BASE_BBL, not independently spatially assigned','counting_rules':{'raw_records':'All source service records, including placeholder geometries','source_defined_entities':'Distinct official DOITT_ID, not independently resolved physical buildings','geometry_parts':'Polygon components after repair; never equals proven building count by assumption','valid_height':'Finite, plausible source relative height >0; converted feet to metres, not independently verified','model_count':'Archives/3dm geometry objects listed separately; 0 current building crosswalk matches','unknown_heights':'Null, source zero and anomalous values remain null; no default height','failures':'Geometry quarantine distinct from HTTP acquisition failures'},'city_source_count':inventory['counts']['all'],'downloaded_raw_records':raw_total,'normalized_records':city['rows'],'unassigned_source_bbl_records':inventory['counts']['unassigned'],'boroughs':rows,'totals':{'valid_source_height_records':sum(r['valid_source_height_records']for r in rows),'unknown_heights':sum(r['unknown_height_records']for r in rows),'anomalous_heights':sum(r['anomalous_height_values']for r in rows),'placeholder_records':sum(r['placeholders']for r in rows),'negative_ground_values_preserved':sum(r['negative_ground_records_preserved']for r in rows),'geometry_repairs':sum(r['geometry_repairs']for r in rows),'failed_geometries':sum(r['failed_geometries']for r in rows),'independently_verified_positions':0,'independently_verified_heights':0,'matched_current_3d_models':0,'unknown_roof_records':city['rows'],'unknown_facade_records':city['rows']},'pilots':{'records':sum(p['normalized_records']for p in pilots),'datasets':[{'path':str(Path(p['source_manifest']).parent),'records':p['normalized_records'],'valid_source_heights':p['valid_height_records'],'failures':p['failed']}for p in pilots],'representation':'GLB linework on declared reference ellipsoid; heights not extruded'},'context':read('reports/context-quality.json'),'pluto':{k:v for k,v in read('reports/pluto-audit.json').items()if k in ['source_version','data_date','rows','borough_rows','pilot_lot_matches','building_values_overwritten']},'model':{'acquired_archives':1,'parsed_3dm_files':1,'geometry_objects':read('reports/official-model-audit.json')['geometry_objects'],'acquisition_year':2014,'matched_current_buildings':0,'unit_reconciliation':'Rhino Feet vs metadata US survey foot unresolved; no model transformation published'},'field_scope_issues':len(read('data/processed/field-conflicts.json')),'imagery':{'acquired_tiles':1,'reference_only':True,'single_tile_refetch_actually_executed':True},'not_acquired':['LiDAR point-cloud tiles','MapPLUTO parcel geometries','Other official 3D community district/park packages','NYS orthophoto raster tiles','current roof/facade per-building evidence','geoid grid/validated terrain'],'consistency_limit':'Dynamic API: end counts, stable ID sets/unique row IDs and timestamps checked; not an atomic historical snapshot. Source age and independent accuracy remain unknown per record.','city_semantic_sha256':city['semantic_sha256'],'processor_sha256':city['processor_sha256']}
report['pilots']['source_records']=report['pilots']['records']
report['pilots']['placeholder_records']=sum(p['placeholder_records']for p in pilots)
report['pilots']['published_real_outlines']=sum(p['normalized_records']-p['placeholder_records']for p in pilots)
report['field_scope_issue_types']={kind:sum(c['type']==kind for c in read('data/processed/field-conflicts.json'))for kind in set(c['type']for c in read('data/processed/field-conflicts.json'))}
atomic_json(ROOT/'reports/data-quality.json',report)
atomic_json(ROOT/'data/manifests/coverage.json',report)
with(ROOT/'reports/borough-coverage.csv').open('w',newline='')as f:
 keys=['borough','raw_records','source_defined_entities','geometry_parts','valid_source_height_records','unknown_height_records','placeholders','geometry_repairs','failed_geometries','matched_legacy_models','acquired_legacy_model_archives'];w=csv.DictWriter(f,fieldnames=keys,extrasaction='ignore',lineterminator='\n');w.writeheader();w.writerows(rows)
# Offline evidence entry points accompany the small published samples, not the full city database.
dest=ROOT/'assets/provenance';dest.mkdir(parents=True,exist_ok=True)
for source,name in [('data/manifests/sources.json','sources.json'),('data/manifests/coverage.json','coverage.json'),('data/manifests/field-priorities.json','field-priorities.json')]:shutil.copyfile(ROOT/source,dest/name)
print('QUALITY_REPORT',raw_total,'PILOT_SOURCE_RECORDS',report['pilots']['source_records'],'PUBLISHED_OUTLINES',report['pilots']['published_real_outlines'],'CITY_PLACEHOLDERS',report['totals']['placeholder_records'])
